package com.ensam.inventia.service.impl;
import com.ensam.inventia.dto.request.*; import com.ensam.inventia.dto.response.*; import io.swagger.v3.oas.annotations.Operation; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor class AuthController { private final AuthServiceImpl service; @Operation(summary="Register user") @PostMapping("/register") ApiResponse<AuthResponse> register(@Valid @RequestBody RegisterRequest r, jakarta.servlet.http.HttpServletResponse res){return ApiResponse.ok(service.register(r, res),"Registered");} @PostMapping("/login") ApiResponse<AuthResponse> login(@Valid @RequestBody LoginRequest r, jakarta.servlet.http.HttpServletResponse res){return ApiResponse.ok(service.login(r, res),"Logged in");} @PostMapping("/refresh") ApiResponse<AuthResponse> refresh(@CookieValue(name="refresh_token", required=true) String refreshToken, jakarta.servlet.http.HttpServletResponse res){return ApiResponse.ok(service.refresh(refreshToken, res),"Token refreshed");} @PostMapping("/logout") ApiResponse<Void> logout(@CookieValue(name="refresh_token", required=false) String refreshToken, jakarta.servlet.http.HttpServletResponse res){service.logout(refreshToken, res); return ApiResponse.ok(null,"Logged out");} @GetMapping("/me") ApiResponse<UserResponse> me(){return ApiResponse.ok(service.me(),"Profile");}}
@RestController @RequestMapping("/api/users") @RequiredArgsConstructor class UserController { private final UserServiceImpl service; @PostMapping @PreAuthorize("hasAuthority('ROLE_ADMIN')") ApiResponse<UserResponse> create(@Valid @RequestBody CreateUserRequest r){return ApiResponse.ok(service.create(r),"Created");} @GetMapping @PreAuthorize("hasAuthority('ROLE_ADMIN')") ApiResponse<PageResponse<UserResponse>> list(Pageable p){return ApiResponse.ok(service.list(p),"Users");} @GetMapping("/{id}") ApiResponse<UserResponse> get(@PathVariable Long id){return ApiResponse.ok(service.get(id),"User");} @PutMapping("/{id}") ApiResponse<UserResponse> update(@PathVariable Long id,@Valid @RequestBody UpdateProfileRequest r){return ApiResponse.ok(service.update(id,r),"Updated");} @PutMapping("/{id}/role") @PreAuthorize("hasAuthority('ROLE_ADMIN')") ApiResponse<UserResponse> roles(@PathVariable Long id,@Valid @RequestBody UpdateRoleRequest r){return ApiResponse.ok(service.roles(id,r),"Role updated");} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('ROLE_ADMIN')") ApiResponse<Void> disable(@PathVariable Long id){service.disable(id); return ApiResponse.ok(null,"Disabled");} @PostMapping("/{id}/enable") @PreAuthorize("hasAuthority('ROLE_ADMIN')") ApiResponse<Void> enable(@PathVariable Long id){service.enable(id); return ApiResponse.ok(null,"Enabled");}}
@RestController @RequestMapping("/api/hackathons") @RequiredArgsConstructor class HackathonController { private final HackathonServiceImpl service; private final TeamServiceImpl teams; @GetMapping ApiResponse<PageResponse<HackathonSummaryResponse>> list(Pageable p){return ApiResponse.ok(service.list(p),"Hackathons");} @GetMapping("/{id}") ApiResponse<HackathonResponse> get(@PathVariable Long id){return ApiResponse.ok(service.get(id),"Hackathon");} @GetMapping("/{id}/analytics") @PreAuthorize("hasAnyAuthority('ROLE_MANAGER','ROLE_ADMIN')") ApiResponse<HackathonAnalyticsResponse> analytics(@PathVariable Long id){return ApiResponse.ok(service.analytics(id),"Analytics");} @PostMapping @PreAuthorize("hasAnyAuthority('ROLE_MANAGER','ROLE_ADMIN')") ApiResponse<HackathonResponse> create(@Valid @RequestBody HackathonRequest r){return ApiResponse.ok(service.create(r),"Created");} @PutMapping("/{id}") @PreAuthorize("hasAnyAuthority('ROLE_MANAGER','ROLE_ADMIN')") ApiResponse<HackathonResponse> update(@PathVariable Long id,@Valid @RequestBody HackathonRequest r){return ApiResponse.ok(service.update(id,r),"Updated");} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('ROLE_ADMIN')") ApiResponse<Void> delete(@PathVariable Long id){service.delete(id); return ApiResponse.ok(null,"Deleted");} @PostMapping("/{id}/teams") ApiResponse<TeamResponse> createTeam(@PathVariable Long id,@Valid @RequestBody TeamRequest r){return ApiResponse.ok(teams.create(id,r),"Team created");} @GetMapping("/{id}/my-team") ApiResponse<TeamResponse> myTeam(@PathVariable Long id){return ApiResponse.ok(service.myTeam(id),"My team");}}
@RestController @RequestMapping("/api/teams") @RequiredArgsConstructor class TeamController { private final TeamServiceImpl teams; private final SubmissionServiceImpl submissions; @GetMapping("/{id}") ApiResponse<TeamResponse> get(@PathVariable Long id){return ApiResponse.ok(teams.get(id),"Team");} @PostMapping("/join") ApiResponse<TeamResponse> join(@Valid @RequestBody JoinTeamRequest r){return ApiResponse.ok(teams.join(r),"Joined team");} @PostMapping("/{id}/members") ApiResponse<TeamResponse> add(@PathVariable Long id,@Valid @RequestBody AddMemberRequest r){return ApiResponse.ok(teams.add(id,r),"Member added");} @DeleteMapping("/{id}") ApiResponse<Void> delete(@PathVariable Long id){teams.delete(id); return ApiResponse.ok(null,"Deleted");} @GetMapping("/{id}/submission") ApiResponse<SubmissionResponse> submission(@PathVariable Long id){return ApiResponse.ok(submissions.get(id),"Submission");} @PostMapping(value="/{id}/submission", consumes=MediaType.MULTIPART_FORM_DATA_VALUE) ApiResponse<SubmissionResponse> submit(@PathVariable Long id,@Valid @RequestPart("metadata") SubmissionRequest r,@RequestPart("file") MultipartFile file){return ApiResponse.ok(submissions.upsert(id,r,file),"Submitted");} @PutMapping(value="/{id}/submission", consumes=MediaType.MULTIPART_FORM_DATA_VALUE) ApiResponse<SubmissionResponse> update(@PathVariable Long id,@Valid @RequestPart("metadata") SubmissionRequest r,@RequestPart(value="file", required=false) MultipartFile file){return ApiResponse.ok(submissions.upsert(id,r,file),"Updated");} @GetMapping("/{id}/submission/download") ResponseEntity<org.springframework.core.io.ByteArrayResource> download(@PathVariable Long id){var d=submissions.download(id); return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+d.fileName()+"\"").body(d.body());} @DeleteMapping("/{id}/submission") ApiResponse<Void> del(@PathVariable Long id){submissions.delete(id); return ApiResponse.ok(null,"Deleted");}}
@RestController @RequestMapping("/api/submissions") @RequiredArgsConstructor class ScoreController { private final ScoreServiceImpl service; @GetMapping("/{id}/scores") @PreAuthorize("hasAnyAuthority('ROLE_MANAGER','ROLE_ADMIN')") ApiResponse<List<ScoreResponse>> list(@PathVariable Long id){return ApiResponse.ok(service.list(id),"Scores");} @PostMapping("/{id}/scores") @PreAuthorize("hasAnyAuthority('ROLE_MANAGER','ROLE_ADMIN')") ApiResponse<ScoreResponse> score(@PathVariable Long id,@Valid @RequestBody ScoreRequest r){return ApiResponse.ok(service.score(id,r),"Scored");}}
@RestController @RequestMapping("/api/dashboard") @RequiredArgsConstructor class DashboardController { private final DashboardServiceImpl service; @GetMapping("/admin") @PreAuthorize("hasAuthority('ROLE_ADMIN')") ApiResponse<DashboardStatsResponse> admin(){return ApiResponse.ok(service.stats(),"Dashboard");} @GetMapping("/manager") @PreAuthorize("hasAnyAuthority('ROLE_MANAGER','ROLE_ADMIN')") ApiResponse<DashboardStatsResponse> manager(){return ApiResponse.ok(service.stats(),"Dashboard");} @GetMapping("/user") ApiResponse<DashboardStatsResponse> user(){return ApiResponse.ok(service.stats(),"Dashboard");}}
@RestController @RequestMapping("/api/hackathons/{id}/export") @RequiredArgsConstructor class ExportController { private final ExportServiceImpl service; @GetMapping("/pdf") @PreAuthorize("hasAnyAuthority('ROLE_MANAGER','ROLE_ADMIN')") ResponseEntity<byte[]> pdf(@PathVariable Long id){return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=inventia-hackathon-"+id+".pdf").body(service.pdf(id));} @GetMapping("/excel") @PreAuthorize("hasAnyAuthority('ROLE_MANAGER','ROLE_ADMIN')") ResponseEntity<byte[]> excel(@PathVariable Long id){return ResponseEntity.ok().contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=inventia-hackathon-"+id+".xlsx").body(service.excel(id));}}
@RestController @RequestMapping("/api/teams/{id}/chat") @RequiredArgsConstructor class ChatController { private final ChatServiceImpl service; @GetMapping ApiResponse<List<ChatMessageResponse>> list(@PathVariable Long id){return ApiResponse.ok(service.list(id),"Chat messages");} @PostMapping ApiResponse<ChatMessageResponse> send(@PathVariable Long id,@Valid @RequestBody ChatMessageRequest r){return ApiResponse.ok(service.send(id,r),"Message sent");}}
